import sys

def main():
    for line in sys.stdin:
        line = line.strip()
        if line == '0':
            break
        parts = line.split()
        n = int(parts[0])
        perm = list(map(int, parts[1:]))
        is_ambiguous = True
        for i in range(n):
            if perm[i] != perm[perm[i] - 1]:
                is_ambiguous = False
                break
        print('ambiguous' if is_ambiguous else 'not ambiguous')

main()
